"use client";

import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { type ComponentProps, type ReactNode, useId, useMemo } from "react";
import { twMerge } from "tailwind-merge";
import { tv, type VariantProps } from "tailwind-variants";
import { spring } from "@/lib/motion-tokens";
import { useChartInteraction } from "./chart-interaction";
import { chartAccentTransition, chartCascadeStep } from "./chart-motion";

export const resourceTreemapChartVariants = tv({
  base: "not-prose w-full text-foreground",
  variants: {
    size: {
      sm: "max-w-[400px]",
      md: "max-w-[600px]",
      lg: "max-w-[780px]",
      full: "max-w-full",
    },
  },
  defaultVariants: { size: "md" },
});

export type ResourceTreemapDatum = {
  label: string;
  value: number;
  unit?: string;
  tone?: string;
};

export type ResourceTreemapChartProps = ComponentProps<"div"> &
  VariantProps<typeof resourceTreemapChartVariants> & {
    data?: ResourceTreemapDatum[];
    title?: ReactNode;
    description?: ReactNode;
    valueFormatter?: (value: number, unit?: string) => string;
    animated?: boolean;
    showTooltip?: boolean;
    showLabels?: boolean;
    height?: number;
    motionDelay?: number;
  };

const defaultData: ResourceTreemapDatum[] = [
  { label: "JavaScript", value: 48, unit: "KB", tone: "chart-1" },
  { label: "Images", value: 28, unit: "KB", tone: "chart-2" },
  { label: "CSS", value: 12, unit: "KB", tone: "chart-4" },
  { label: "Fonts", value: 8, unit: "KB", tone: "chart-3" },
  { label: "Other", value: 4, unit: "KB", tone: "muted-foreground" },
];

const fallbackTones = [
  "var(--chart-1)",
  "var(--chart-2)",
  "var(--chart-3)",
  "var(--chart-4)",
  "var(--foreground)",
] as const;

function resolveTone(tone: string | undefined, index: number) {
  if (!tone) return fallbackTones[index % fallbackTones.length];
  if (
    tone.startsWith("var(") ||
    tone.startsWith("color-mix(") ||
    tone.startsWith("oklch(")
  )
    return tone;
  return `var(--${tone})`;
}

function clamp(v: number, lo: number, hi: number) {
  return Math.min(Math.max(v, lo), hi);
}

type TileRect = {
  x: number;
  y: number;
  w: number;
  h: number;
};

function layoutTreemap(
  values: number[],
  x: number,
  y: number,
  width: number,
  height: number,
): TileRect[] {
  if (values.length === 0) return [];
  if (values.length === 1) return [{ x, y, w: width, h: height }];

  const total = values.reduce((s, v) => s + v, 0);
  let leftSum = 0;
  let splitIdx = 1;
  for (let i = 0; i < values.length - 1; i++) {
    leftSum += values[i];
    splitIdx = i + 1;
    if (leftSum / total >= 0.5) break;
  }

  const leftFraction = leftSum / total;
  const leftValues = values.slice(0, splitIdx);
  const rightValues = values.slice(splitIdx);

  if (width >= height) {
    const lw = width * leftFraction;
    return [
      ...layoutTreemap(leftValues, x, y, lw, height),
      ...layoutTreemap(rightValues, x + lw, y, width - lw, height),
    ];
  }

  const th = height * leftFraction;
  return [
    ...layoutTreemap(leftValues, x, y, width, th),
    ...layoutTreemap(rightValues, x, y + th, width, height - th),
  ];
}

export function ResourceTreemapChart({
  className,
  size,
  data = defaultData,
  title = "Resource Treemap",
  description = "Page weight breakdown by resource type",
  valueFormatter,
  animated = true,
  showTooltip = true,
  showLabels = true,
  height = 320,
  motionDelay = 0,
  ...props
}: ResourceTreemapChartProps) {
  const shouldReduceMotion = useReducedMotion();
  const rawId = useId();
  const id = rawId.replace(/:/g, "");

  const motionEnabled = animated && !shouldReduceMotion;

  const normalizedData = useMemo(
    () => data.filter((d) => Number.isFinite(d.value) && d.value > 0),
    [data],
  );
  const { activeIndex, getItemProps, hasEnteredView, interactionProps } =
    useChartInteraction(id, normalizedData.length);

  const total = useMemo(
    () => normalizedData.reduce((s, d) => s + d.value, 0),
    [normalizedData],
  );

  const sorted = useMemo(
    () => [...normalizedData].sort((a, b) => b.value - a.value),
    [normalizedData],
  );

  const fmt = (d: ResourceTreemapDatum) => {
    if (valueFormatter) return valueFormatter(d.value, d.unit);
    return d.unit ? `${d.value}${d.unit}` : String(d.value);
  };

  // SVG layout
  const viewBoxWidth = 560;
  const viewBoxHeight = 320;
  const gap = 3;
  const outerPad = 0;

  const tiles = useMemo(() => {
    const values = sorted.map((d) => d.value);
    const rects = layoutTreemap(
      values,
      outerPad,
      outerPad,
      viewBoxWidth - outerPad * 2,
      viewBoxHeight - outerPad * 2,
    );
    return sorted.map((d, i) => ({
      ...d,
      i,
      originalIndex: normalizedData.indexOf(d),
      color: resolveTone(d.tone, i),
      rect: rects[i],
      percent: Math.round((d.value / total) * 100),
    }));
  }, [sorted, total, normalizedData]);

  const activePoint = activeIndex !== null ? tiles[activeIndex] : null;

  const tooltipWidth = 168;
  const tooltipHeight = 64;
  const tooltipX = activePoint
    ? clamp(
        activePoint.rect.x + activePoint.rect.w / 2 - tooltipWidth / 2,
        2,
        viewBoxWidth - tooltipWidth - 2,
      )
    : 0;
  const tooltipY = activePoint
    ? clamp(
        activePoint.rect.y + activePoint.rect.h / 2 - tooltipHeight - 10,
        2,
        viewBoxHeight - tooltipHeight - 2,
      )
    : 0;

  return (
    <div
      data-slot="resource-treemap-chart"
      className={twMerge(resourceTreemapChartVariants({ size }), className)}
      {...interactionProps}
      {...props}
    >
      <div data-slot="resource-treemap-chart-header" className="mb-3">
        <h3 className="truncate text-sm font-semibold tracking-tight text-foreground">
          {title}
        </h3>
        {description ? (
          <p className="mt-1 text-xs leading-5 text-muted-foreground">
            {description}
          </p>
        ) : null}
      </div>

      <div
        data-slot="resource-treemap-chart-plot"
        className="overflow-hidden rounded-xl"
        style={{ height }}
      >
        {!motionEnabled || hasEnteredView ? (
          <svg
            viewBox={`0 0 ${viewBoxWidth} ${viewBoxHeight}`}
            className="size-full"
            role="img"
            aria-labelledby={`${id}-title`}
          >
            <title id={`${id}-title`}>{String(title)}</title>
            <defs>
              {tiles.map((tile) => (
                <radialGradient
                  key={`grad-${tile.i}`}
                  id={`${id}-grad-${tile.i}`}
                  cx="30%"
                  cy="28%"
                  r="80%"
                >
                  <stop
                    offset="0%"
                    stopColor={`color-mix(in oklab, ${tile.color} 55%, white)`}
                  />
                  <stop offset="55%" stopColor={tile.color} />
                  <stop
                    offset="100%"
                    stopColor={`color-mix(in oklab, ${tile.color} 70%, black)`}
                  />
                </radialGradient>
              ))}
            </defs>

            {tiles.map((tile) => {
              const isActive = activeIndex === tile.i;
              const r = tile.rect;
              const rx = r.x + gap / 2;
              const ry = r.y + gap / 2;
              const rw = Math.max(0, r.w - gap);
              const rh = Math.max(0, r.h - gap);
              const cx = rx + rw / 2;
              const cy = ry + rh / 2;
              const isLargest = tile.i === 0;
              const showLabel = showLabels && rw > 60 && rh > 36;
              const showValue = rw > 60 && rh > 54;

              return (
                <motion.g
                  key={`tile-${tile.i}`}
                  data-slot="resource-treemap-chart-tile"
                  tabIndex={0}
                  role="button"
                  aria-label={`${tile.label}: ${fmt(tile)}, ${tile.percent}%`}
                  {...getItemProps(tile.i)}
                  className="outline-none"
                  style={{ transformOrigin: `${cx}px ${cy}px` }}
                  animate={{
                    scale: isActive ? 1.012 : 1,
                  }}
                  transition={chartAccentTransition}
                >
                  <motion.rect
                    x={rx}
                    y={ry}
                    width={rw}
                    height={rh}
                    rx="6"
                    fill={`url(#${id}-grad-${tile.i})`}
                    fillOpacity={isActive ? 1 : 0.88}
                    stroke="var(--background)"
                    strokeWidth="0"
                    initial={
                      motionEnabled
                        ? { scale: 0, opacity: 0 }
                        : { scale: 1, opacity: 0.88 }
                    }
                    animate={{ scale: 1, opacity: isActive ? 1 : 0.88 }}
                    transition={{
                      scale: {
                        ...spring.moderate,
                        delay: motionDelay + tile.i * chartCascadeStep,
                      },
                      opacity: {
                        ...chartAccentTransition,
                        delay: motionDelay + tile.i * chartCascadeStep,
                      },
                    }}
                    style={{ transformOrigin: `${cx}px ${cy}px` }}
                  />

                  {/* Highlight edge on active */}
                  {isActive ? (
                    <rect
                      x={rx}
                      y={ry}
                      width={rw}
                      height={rh}
                      rx="6"
                      fill="none"
                      stroke="white"
                      strokeOpacity="0.25"
                      strokeWidth="1.5"
                      pointerEvents="none"
                    />
                  ) : null}

                  {/* Percentage badge for large tiles */}
                  {isLargest && rw > 100 ? (
                    <motion.text
                      x={rx + 10}
                      y={ry + 18}
                      fill="white"
                      fillOpacity="0.55"
                      className="text-[11px] font-semibold tabular-nums"
                      initial={motionEnabled ? { opacity: 0 } : false}
                      animate={{ opacity: 1 }}
                      transition={{
                        ...chartAccentTransition,
                        delay: motionDelay + 0.5,
                      }}
                    >
                      {tile.percent}%
                    </motion.text>
                  ) : null}

                  {showLabel ? (
                    <motion.text
                      x={cx}
                      y={showValue ? cy - 8 : cy + 4}
                      textAnchor="middle"
                      dominantBaseline="middle"
                      fill="white"
                      fillOpacity="0.92"
                      className="text-[12px] font-semibold"
                      initial={motionEnabled ? { opacity: 0 } : false}
                      animate={{ opacity: 1 }}
                      transition={{
                        ...chartAccentTransition,
                        delay: motionDelay + tile.i * chartCascadeStep + 0.32,
                      }}
                    >
                      {tile.label}
                    </motion.text>
                  ) : null}

                  {showValue ? (
                    <motion.text
                      x={cx}
                      y={cy + 10}
                      textAnchor="middle"
                      dominantBaseline="middle"
                      fill="white"
                      fillOpacity="0.65"
                      className="text-[11px] font-medium tabular-nums"
                      initial={motionEnabled ? { opacity: 0 } : false}
                      animate={{ opacity: 1 }}
                      transition={{
                        ...chartAccentTransition,
                        delay: motionDelay + tile.i * chartCascadeStep + 0.4,
                      }}
                    >
                      {fmt(tile)}
                    </motion.text>
                  ) : null}
                </motion.g>
              );
            })}

            {/* Tooltip */}
            <AnimatePresence>
              {showTooltip && activePoint ? (
                <motion.g
                  data-slot="resource-treemap-chart-tooltip"
                  pointerEvents="none"
                  initial={
                    motionEnabled
                      ? {
                          opacity: 0,
                          x: tooltipX,
                          y: tooltipY + 6,
                          scale: 0.97,
                        }
                      : false
                  }
                  animate={{ opacity: 1, x: tooltipX, y: tooltipY, scale: 1 }}
                  exit={{
                    opacity: 0,
                    x: tooltipX,
                    y: tooltipY + 4,
                    scale: 0.97,
                  }}
                  transition={spring.fast}
                >
                  <rect
                    width={tooltipWidth}
                    height={tooltipHeight}
                    rx="10"
                    fill="var(--popover)"
                    stroke="var(--border)"
                  />
                  <circle cx="14" cy="18" r="4.5" fill={activePoint.color} />
                  <text
                    x="26"
                    y="22"
                    fill="var(--popover-foreground)"
                    className="text-[12px] font-semibold"
                  >
                    {activePoint.label}
                  </text>
                  <text
                    x="14"
                    y="40"
                    fill="var(--muted-foreground)"
                    className="text-[10.5px] font-medium"
                  >
                    Size
                  </text>
                  <text
                    x={tooltipWidth - 14}
                    y="40"
                    textAnchor="end"
                    fill="var(--popover-foreground)"
                    className="text-[10.5px] font-semibold tabular-nums"
                  >
                    {fmt(activePoint)}
                  </text>
                  <text
                    x="14"
                    y="54"
                    fill="var(--muted-foreground)"
                    className="text-[10.5px] font-medium"
                  >
                    Share
                  </text>
                  <text
                    x={tooltipWidth - 14}
                    y="54"
                    textAnchor="end"
                    fill="var(--popover-foreground)"
                    className="text-[10.5px] font-semibold tabular-nums"
                  >
                    {activePoint.percent}%
                  </text>
                </motion.g>
              ) : null}
            </AnimatePresence>
          </svg>
        ) : null}
      </div>
    </div>
  );
}

"use client";

import {
  type FocusEvent,
  type KeyboardEvent,
  type PointerEvent,
  useCallback,
  useEffect,
  useState,
} from "react";

type ChartItemElement = HTMLElement | SVGElement;

export type ChartInteractionProps = {
  "aria-pressed": boolean;
  "data-chart-item-index": number;
  onBlur: (event: FocusEvent<ChartItemElement>) => void;
  onClick: () => void;
  onFocus: () => void;
  onKeyDown: (event: KeyboardEvent<ChartItemElement>) => void;
  onPointerEnter: (event: PointerEvent<ChartItemElement>) => void;
  onPointerLeave: (event: PointerEvent<ChartItemElement>) => void;
};

export type ChartInteraction = {
  activeIndex: number | null;
  clearSelection: () => void;
  getItemProps: (index: number) => ChartInteractionProps;
  interactionProps: {
    "data-chart-interaction": string;
    "data-chart-viewport": string;
    onPointerLeave: (event: PointerEvent<ChartItemElement>) => void;
  };
  hasEnteredView: boolean;
  selectedIndex: number | null;
  selectIndex: (index: number | null) => void;
};

export function useChartInView(viewportId: string): boolean {
  const [hasEnteredView, setHasEnteredView] = useState(false);

  useEffect(() => {
    if (hasEnteredView) return;

    const root = document.querySelector(
      `[data-chart-viewport="${viewportId}"]`,
    );

    if (!root || typeof IntersectionObserver === "undefined") {
      setHasEnteredView(true);
      return;
    }

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (!entry?.isIntersecting) return;
        setHasEnteredView(true);
        observer.disconnect();
      },
      { threshold: 0.2 },
    );

    observer.observe(root);
    return () => observer.disconnect();
  }, [hasEnteredView, viewportId]);

  return hasEnteredView;
}

/**
 * Shared intent model for SVG charts: hover/focus is temporary while click,
 * tap, Enter, or Space pins a selection until Escape or an outside press.
 */
export function useChartInteraction(
  interactionId: string,
  itemCount: number,
): ChartInteraction {
  const [hoveredIndex, setHoveredIndex] = useState<number | null>(null);
  const [selectedIndex, setSelectedIndex] = useState<number | null>(null);
  const hasEnteredView = useChartInView(interactionId);

  useEffect(() => {
    setHoveredIndex((index) =>
      index !== null && index >= itemCount ? null : index,
    );
    setSelectedIndex((index) =>
      index !== null && index >= itemCount ? null : index,
    );
  }, [itemCount]);

  useEffect(() => {
    if (selectedIndex === null) return;

    function handlePointerDown(event: globalThis.PointerEvent) {
      const target = event.target;

      if (
        target instanceof Element &&
        target.closest(`[data-chart-interaction="${interactionId}"]`)
      ) {
        return;
      }

      setSelectedIndex(null);
      setHoveredIndex(null);
    }

    function handleKeyDown(event: globalThis.KeyboardEvent) {
      if (event.key !== "Escape") return;
      setSelectedIndex(null);
      setHoveredIndex(null);
    }

    document.addEventListener("pointerdown", handlePointerDown);
    document.addEventListener("keydown", handleKeyDown);

    return () => {
      document.removeEventListener("pointerdown", handlePointerDown);
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, [interactionId, selectedIndex]);

  const focusItem = useCallback(
    (index: number) => {
      const root = document.querySelector<HTMLElement>(
        `[data-chart-interaction="${interactionId}"]`,
      );
      const item = root?.querySelector<HTMLElement>(
        `[data-chart-item-index="${index}"]`,
      );
      item?.focus();
    },
    [interactionId],
  );

  const getItemProps = useCallback(
    (index: number): ChartInteractionProps => ({
      "aria-pressed": selectedIndex === index,
      "data-chart-item-index": index,
      onBlur: (event) => {
        if (!event.currentTarget.contains(event.relatedTarget)) {
          setHoveredIndex(null);
        }
      },
      onClick: () => {
        setHoveredIndex(null);
        setSelectedIndex((current) => (current === index ? null : index));
      },
      onFocus: () => setHoveredIndex(index),
      onKeyDown: (event) => {
        if (event.key === "Enter" || event.key === " ") {
          event.preventDefault();
          setHoveredIndex(null);
          setSelectedIndex((current) => (current === index ? null : index));
          return;
        }

        const direction =
          event.key === "ArrowRight" || event.key === "ArrowDown"
            ? 1
            : event.key === "ArrowLeft" || event.key === "ArrowUp"
              ? -1
              : 0;

        if (!direction || itemCount < 2) return;
        event.preventDefault();
        const nextIndex = (index + direction + itemCount) % itemCount;
        setHoveredIndex(nextIndex);
        focusItem(nextIndex);
      },
      onPointerEnter: (event) => {
        if (event.pointerType !== "touch") setHoveredIndex(index);
      },
      onPointerLeave: (event) => {
        if (event.pointerType !== "touch") setHoveredIndex(null);
      },
    }),
    [focusItem, itemCount, selectedIndex],
  );

  return {
    activeIndex: hoveredIndex ?? selectedIndex,
    clearSelection: () => {
      setHoveredIndex(null);
      setSelectedIndex(null);
    },
    getItemProps,
    interactionProps: {
      "data-chart-interaction": interactionId,
      "data-chart-viewport": interactionId,
      onPointerLeave: (event) => {
        if (event.pointerType !== "touch") setHoveredIndex(null);
      },
    },
    hasEnteredView,
    selectedIndex,
    selectIndex: (index) => {
      setHoveredIndex(null);
      setSelectedIndex(
        index !== null && index >= 0 && index < itemCount ? index : null,
      );
    },
  };
}

"use client";

import {
  duration,
  ease,
  spring,
  stagger,
} from "@/lib/motion-tokens";
import { surfaceClasses } from "@/lib/surface-classes";
import { useSurface } from "@/lib/surface-context";

/**
 * Shared motion for the SVG chart family, so twelve charts move on one system
 * instead of twelve hand-tuned timings.
 *
 * - A chart *tooltip* is a popover: it sits `offset` 2 above whatever substrate
 *   the chart is on, and it lands on the `fast` tier because a reading that
 *   trails the cursor reads as lag.
 * - An *accent* — a point growing, a bar highlighting, a ring blooming under
 *   hover — is micro-feedback, also `fast`.
 * - A *draw-on* — a line, an area, a bar revealing itself — is a shape over
 *   time, so it is a tween on `ease.decelerate`. Its length is data-scaled by
 *   the caller (a longer series draws longer); only the curve is fixed here.
 * - A whole chart *settling in* on scroll rides the same decelerate tween at
 *   the `slow` duration.
 */

/** The tooltip surface: `surfaceClasses` at the conventional popover offset. */
export function useChartTooltipSurface(): { level: number; className: string } {
  const level = Math.min(useSurface() + 2, 8);
  return { level, className: surfaceClasses(level) };
}

/** Tooltip enter/exit — spread onto the tooltip's `motion` element. */
export const chartTooltipMotion = {
  initial: { opacity: 0, y: 6, scale: 0.98 },
  animate: { opacity: 1, y: 0, scale: 1 },
  exit: { opacity: 0, y: 4, scale: 0.98, transition: spring.fast.exit },
  transition: spring.fast,
} as const;

/** Point / bar / segment accent under hover, focus or selection. */
export const chartAccentTransition = spring.fast;

/** A cursor line or crosshair fading in with the pointer. */
export const chartCursorTransition = {
  duration: duration.fast,
  ease: ease.standard,
};

/** Per-mark delay when a series staggers itself in (bars, points, bands). */
export const chartStaggerStep = stagger.moderate;

/** Tighter step for a dense grid or diagonal wave (a heatmap filling in), where
 *  `chartStaggerStep` across dozens of cells would drag. */
export const chartCascadeStep = stagger.fast;

/**
 * The draw-on transition. Pass the data-scaled length in seconds; the ease is
 * always `decelerate` so the reveal glides to a stop.
 */
export function chartDraw(seconds: number = duration.slow) {
  return { duration: seconds, ease: ease.decelerate } as const;
}

/** A whole chart or a band settling in when it scrolls into view. */
export const chartRevealTransition = {
  duration: duration.slow,
  ease: ease.decelerate,
} as const;
